const request = $("Prepare GetSlots Request").first().json;
const timeZone = request.timezone || "America/Chicago";
const slotMinutes = 30;
const slotMs = slotMinutes * 60 * 1000;
const rangeStart = new Date(request.starttime);
const rangeEnd = new Date(request.endtime);

if (Number.isNaN(rangeStart.getTime()) || Number.isNaN(rangeEnd.getTime()) || rangeEnd <= rangeStart) {
  throw new Error("The requested time range is invalid.");
}

const partFormatter = new Intl.DateTimeFormat("en-US", {
  timeZone, weekday: "short", year: "numeric", month: "2-digit", day: "2-digit",
  hour: "2-digit", minute: "2-digit", hourCycle: "h23",
});
const displayFormatter = new Intl.DateTimeFormat("en-US", {
  timeZone, weekday: "long", month: "long", day: "numeric",
  hour: "numeric", minute: "2-digit", hour12: true,
});

function localParts(date) {
  return Object.fromEntries(partFormatter.formatToParts(date)
    .filter(({ type }) => type !== "literal")
    .map(({ type, value }) => [type, value]));
}

function eventDate(value) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

// Google Calendar returns one item per event. Ignore cancelled and transparent events.
const busy = $input.all().map(({ json }) => {
  if (json.status === "cancelled" || json.transparency === "transparent") return null;
  const start = eventDate(json.start?.dateTime || json.start?.date);
  const end = eventDate(json.end?.dateTime || json.end?.date);
  return start && end && end > start ? { start, end } : null;
}).filter(Boolean);

const availableSlots = [];
const firstSlotMs = Math.ceil(rangeStart.getTime() / slotMs) * slotMs;
for (let startMs = firstSlotMs; startMs + slotMs <= rangeEnd.getTime(); startMs += slotMs) {
  const start = new Date(startMs);
  const end = new Date(startMs + slotMs);
  const localStart = localParts(start);
  const localEnd = localParts(end);
  const hour = Number(localStart.hour);
  const weekday = localStart.weekday;

  // Monday–Friday, 9:00 AM–6:00 PM in America/Chicago.
  const isBusinessDay = weekday !== "Sat" && weekday !== "Sun";
  const isWithinHours = hour >= 9 && hour < 18 && (Number(localEnd.hour) < 18 || (Number(localEnd.hour) === 18 && Number(localEnd.minute) === 0));
  const staysSameLocalDay = localStart.year === localEnd.year && localStart.month === localEnd.month && localStart.day === localEnd.day;
  const overlapsBusy = busy.some(({ start: busyStart, end: busyEnd }) => start < busyEnd && end > busyStart);

  if (isBusinessDay && isWithinHours && staysSameLocalDay && !overlapsBusy) {
    availableSlots.push({
      startTime: start.toISOString(),
      endTime: end.toISOString(),
      display: displayFormatter.format(start),
    });
  }
}

const result = availableSlots.length
  ? "Available 30-minute appointment start times: " + availableSlots.map(({ display }) => display).join("; ")
  : "No 30-minute appointment times are available in the requested range.";

return [{
  json: {
    results: [{ toolCallId: request.toolCallId, result }],
    availableSlots,
  },
}];

const escapeStringForJson = (str) => {
    return str
        .replace(/\\/g, '\\\\') // Escape backslashes
        .replace(/"/g, '\\"')    // Escape double quotes
        .replace(/\n/g, '\\n')   // Escape newlines
        .replace(/\r/g, '\\r')   // Escape carriage returns
        .replace(/\t/g, '\\t');  // Escape tabs
};

// Escape the notes field
$input.item.json.notes = escapeStringForJson($input.item.json.notes);

return $input.item;

// Get all input items
const items = $input.all();

// Loop through each item
for (const item of items) {
  // Get the values from the current item's JSON data
  const startTimeUTC = item.json.starttime;
  const endTimeUTC = item.json.endtime;
  const targetTimeZone = item.json.timeZone; // e.g., "America/Chicago"

  // Basic validation: ensure the necessary fields exist
  if (!startTimeUTC || !endTimeUTC || !targetTimeZone) {
    console.warn(`Skipping item due to missing time data or timezone. Item JSON: ${JSON.stringify(item.json)}`);
    item.json.conversionError = "Missing starttime, endtime, or timeZone";
    continue; // Move to the next item
  }

  try {
    // --- Start Time Conversion ---
    // Parse the original UTC ISO string using Luxon (NO $ prefix)
    const startDt = luxon.DateTime.fromISO(startTimeUTC, { zone: 'utc' });

    // Convert the DateTime object to the target timezone
    const startDtTargetZone = startDt.setZone(targetTimeZone);

    // Check if the conversion was valid
    if (!startDtTargetZone.isValid) {
      throw new Error(`Failed to convert start time. Reason: ${startDtTargetZone.invalidReason || 'Unknown'}`);
    }

    // Format the result back into an ISO string with the correct offset
    item.json.starttime = startDtTargetZone.toISO();

    // --- End Time Conversion ---
    // Parse the original UTC ISO string using Luxon (NO $ prefix)
    const endDt = luxon.DateTime.fromISO(endTimeUTC, { zone: 'utc' });

    // Convert the DateTime object to the target timezone
    const endDtTargetZone = endDt.setZone(targetTimeZone);

     // Check if the conversion was valid
    if (!endDtTargetZone.isValid) {
      throw new Error(`Failed to convert end time. Reason: ${endDtTargetZone.invalidReason || 'Unknown'}`);
    }

    // Format the result back into an ISO string with the correct offset
    item.json.endtime = endDtTargetZone.toISO();

    // Optionally remove the error flag if conversion was successful this time
    delete item.json.conversionError;

  } catch (error) {
    console.error(`Error converting time for item: ${JSON.stringify(item.json)}. Error: ${error.message}`);
    // Add/update the error flag to the item's JSON
    item.json.conversionError = error.message;
  }
}
// Return the modified array of items
return items;

const original = $json;
const raw = original.error?.message ?? original.error?.description ?? original.message ?? 'Booking could not be completed.';
const text = String(raw);
const bookingMessage = text.includes('no_available_users_found_error')
  ? 'This time slot is no longer available.'
  : text;
return { json: { ...original, bookingMessage } };

const original = $json;

const body = original.body ?? {};
const message = body.message ?? {};

const calls =
  message.toolCallList ??
  message.toolWithToolCallList ??
  message.toolCalls ??
  [];

const wrapper = calls.find((item) =>
  String(
    item.name ??
    item.toolCall?.function?.name ??
    item.function?.name ??
    ''
  ).toLowerCase() === 'updateslots'
) ?? calls[0] ?? {};

const toolCall = wrapper.toolCall ?? wrapper;

let args =
  toolCall.parameters ??
  toolCall.function?.arguments ??
  wrapper.parameters ??
  wrapper.function?.arguments ??
  {};

if (typeof args === 'string') {
  args = JSON.parse(args);
}

const name = String(args.fullName ?? args.name ?? '').trim();
const email = String(args.email ?? '').trim().toLowerCase();

return {
  json: {
    ...original,

    Calls: calls,
    toolCallId: String(toolCall.id ?? wrapper.id ?? ''),
    call: {
      id: String(message.call?.id ?? ''),
    },

    name,
    fullName: name,
    email,
    customer_number: String(message.call?.customer?.number ?? ''),

    eventId: String(args.eventId ?? args.event_id ?? ''),
    starttime: String(args.starttime ?? ''),
    endtime: String(args.endtime ?? ''),

    Rescheduled_starttime: String(
      args.rescheduled_starttime ?? args.newStarttime ?? args.new_starttime ?? ''
    ),
    Rescheduled_endtime: String(
      args.rescheduled_endtime ?? args.newEndtime ?? args.new_endtime ?? ''
    ),
  },
};

const original = $input.first().json;
const message = original.body?.message ?? {};
const calls = message.toolCallList ?? message.toolWithToolCallList ?? message.toolCalls ?? [];
const wrapper = calls.find((item) => String(
  item.name ?? item.toolCall?.function?.name ?? item.function?.name ?? ''
).toLowerCase() === 'bookslots') ?? calls[0] ?? {};
const toolCall = wrapper.toolCall ?? wrapper;
let args = toolCall.parameters ?? toolCall.function?.arguments ?? wrapper.parameters ?? wrapper.function?.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { throw new Error('BookSlots arguments are not valid JSON.'); }
}
const start = new Date(args.starttime);
const end = new Date(args.endtime);
const fullName = String(args.fullName ?? args.name ?? '').trim();
const email = String(args.email ?? '').trim().toLowerCase();
const notes = String(args.notes ?? '').trim();
const appointmentType = String(args.appointmentType ?? args.Title ?? args.title ?? 'Primary consultation').trim();
const toolCallId = String(toolCall.id ?? wrapper.id ?? '');
const isValid = Boolean(toolCallId && fullName) && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) &&
  !Number.isNaN(start.getTime()) && !Number.isNaN(end.getTime()) && end > start;
return [{ json: {
  ...original,
  toolCallId,
  callId: String(message.call?.id ?? ''),
  fullName, email, notes, appointmentType,
  starttime: Number.isNaN(start.getTime()) ? '' : start.toISOString(),
  endtime: Number.isNaN(end.getTime()) ? '' : end.toISOString(),
  Title: appointmentType + ' – ' + (fullName || 'New caller'),
  timeZone: 'America/Chicago',
  customer_number: String(message.call?.customer?.number ?? ''),
  isValid,
} }];

